import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, mkdir, readFile, rm, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { buildSourceManifest, runCommandMatrix, runReleaseVerification } from '../scripts/release-verify.mjs';
import { captureDashboard } from '../scripts/capture-dashboard.mjs';

test('source manifest binds the canonical source content actually verified and ignores generated dist output',async(t)=>{
  const root=await mkdtemp(path.join(os.tmpdir(),'forge-source-manifest-'));t.after(()=>rm(root,{recursive:true,force:true}));
  await mkdir(path.join(root,'src'),{recursive:true});await mkdir(path.join(root,'dist','verification-runs'),{recursive:true});
  await writeFile(path.join(root,'src','index.mjs'),'export const value=1;\n');await writeFile(path.join(root,'dist','verification-runs','old.json'),'generated');
  const first=await buildSourceManifest(root);await writeFile(path.join(root,'src','index.mjs'),'export const value=2;\n');const second=await buildSourceManifest(root);
  assert.equal(first.files,1);assert.notEqual(first.sha256,second.sha256);assert.equal(first.entries[0].relativePath,'src/index.mjs');
});

test('source manifest treats text line endings canonically without weakening content binding',async(t)=>{
  const root=await mkdtemp(path.join(os.tmpdir(),'forge-source-eol-'));t.after(()=>rm(root,{recursive:true,force:true}));
  await mkdir(path.join(root,'src'),{recursive:true});
  const source=path.join(root,'src','index.mjs');
  await writeFile(source,'export const value=1;\r\n');const crlf=await buildSourceManifest(root);
  await writeFile(source,'export const value=1;\n');const lf=await buildSourceManifest(root);
  await writeFile(source,'export const value=2;\n');const changed=await buildSourceManifest(root);
  assert.equal(crlf.sha256,lf.sha256);
  assert.notEqual(lf.sha256,changed.sha256);
});

test('release command matrix records all independent checks after a failure',async()=>{
  const results=await runCommandMatrix([`${process.execPath} -e "process.exit(7)"`,`${process.execPath} -e "process.stdout.write('continued')"`]);
  assert.equal(results.length,2);assert.equal(results[0].exitCode,7);assert.equal(results[1].exitCode,0);assert.match(results[1].rawOutput,/continued/);
});

test('dashboard evidence is generated by a portable Node entry point into an isolated output directory',async(t)=>{
  const root=await mkdtemp(path.join(os.tmpdir(),'forge-dashboard-output-'));t.after(()=>rm(root,{recursive:true,force:true}));
  const result=await captureDashboard({outputDirectory:root});
  assert.equal(result.renderer,'forgeos-svg');assert.match(await readFile(result.svg,'utf8'),/^<svg/);assert.equal((await readFile(path.join(root,'dashboard-renderer.txt'),'utf8')).trim(),'forgeos-svg');
});

test('release verifier writes immutable run output outside source evidence and can operate with Git metadata optional',async(t)=>{
  const out=await mkdtemp(path.join(os.tmpdir(),'forge-verification-output-'));t.after(()=>rm(out,{recursive:true,force:true}));
  const messages=[];const originalLog=console.log;console.log=(message)=>messages.push(String(message));
  let result;try{result=await runReleaseVerification({commands:[`${process.execPath} -e "process.stdout.write('ok')"`],outputRoot:out,allowDirty:true});}finally{console.log=originalLog;}
  const {report,outputDirectory}=result;
  assert.equal(report.status,'pass');assert.ok(messages.every((message)=>!message.includes('null/null')));assert.ok(messages.some((message)=>message.includes('tests not run')));assert.ok(report.source.manifestSha256);assert.equal(report.source.manifestAlgorithm,'sha256-canonical-text-v1');assert.match(outputDirectory,/verify_/);assert.equal(JSON.parse(await readFile(path.join(outputDirectory,'verification-report.json'),'utf8')).source.manifestSha256,report.source.manifestSha256);
});
